<?php
declare(strict_types=1); require dirname(__DIR__) . '/app/core/bootstrap.php'; require_role('technician'); $user=current_user(); $ticketId=filter_input(INPUT_GET,'ticket_id',FILTER_VALIDATE_INT) ?: null; $ticket=$ticketId ? (new Ticket($pdo))->findForUser($ticketId,(int)$user['id'],'technician') : null; if($ticketId && !$ticket){http_response_code(404);exit('Ticket not found.');} $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ $data=['maintenance_type'=>post_text('maintenance_type'),'diagnosis'=>post_text('diagnosis'),'actions_taken'=>post_text('actions_taken'),'result'=>post_text('result'),'start_date'=>post_text('start_date'),'end_date'=>post_text('end_date'),'status'=>post_text('status'),'observations'=>post_text('observations')]; if(!verify_csrf_token($_POST['csrf_token']??null))$errors[]='Invalid form token.'; if(!valid_enum($data['maintenance_type'],['preventive','corrective'])||!valid_enum($data['status'],['planned','in_progress','completed']))$errors[]='Invalid maintenance type or status.'; if(!$ticketId && $data['maintenance_type'] !== 'preventive')$errors[]='Standalone maintenance must be preventive.'; foreach(['start_date','end_date'] as $field)if($data[$field]!==''&&!valid_date_value($data[$field],'Y-m-d'))$errors[]='Invalid date.'; if(!$errors){$maintenanceId=(new Maintenance($pdo))->create($ticketId,(int)$user['id'],$data); if($ticketId && in_array($data['status'],['in_progress','completed'],true))(new Ticket($pdo))->updateStatus($ticketId,$data['status']==='completed'?'resolved':'in_progress',(int)$user['id']); flash('message','Maintenance recorded.'); redirect('maintenance_task.php?maintenance_id='.$maintenanceId);} }
require dirname(__DIR__).'/app/views/layout.php'; page_header('Record maintenance'); ?><h1><?= $ticket ? 'Maintenance: ' . e($ticket['title']) : 'Preventive maintenance' ?></h1><?php foreach($errors as $error):?><p class="error"><?=e($error)?></p><?php endforeach;?><section class="panel"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Type</label><select name="maintenance_type"><option value="preventive" <?= !$ticket ? 'selected' : '' ?>>Preventive</option><option value="corrective">Corrective</option></select><label>Diagnosis</label><textarea name="diagnosis"></textarea><label>Actions taken</label><textarea name="actions_taken"></textarea><label>Result</label><textarea name="result"></textarea><div class="grid"><p><label>Start date</label><input type="date" name="start_date"></p><p><label>End date</label><input type="date" name="end_date"></p><p><label>Status</label><select name="status"><option>planned</option><option>in_progress</option><option>completed</option></select></p></div><label>Observations</label><textarea name="observations"></textarea><button type="submit">Save maintenance</button></form></section><?php page_footer(); ?>